import os

FILES = {'requirements.txt': 'streamlit>=1.30.0\npandas>=2.0.0\nrequests>=2.31.0\nsqlalchemy>=2.0.0\nplotly>=5.18.0\npytest>=7.4.0\npytest-cov>=4.1.0\npython-dotenv>=1.0.0\nnumpy>=1.24.0\n', '.env.example': 'RAPIDAPI_KEY=your_rapidapi_key_here\nRAPIDAPI_HOST=cricbuzz-cricket.p.rapidapi.com\nDATABASE_URL=sqlite:///data/cricket.db\n', 'config.py': 'import os\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nRAPIDAPI_KEY = os.getenv("RAPIDAPI_KEY", "")\nRAPIDAPI_HOST = os.getenv("RAPIDAPI_HOST", "cricbuzz-cricket.p.rapidapi.com")\nDATABASE_URL = os.getenv("DATABASE_URL", "sqlite:///data/cricket.db")\nBASE_API_URL = f"https://{RAPIDAPI_HOST}"\n', 'sql/schema.sql': "PRAGMA foreign_keys = ON;\n\nCREATE TABLE IF NOT EXISTS teams (\n    team_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    team_name TEXT NOT NULL UNIQUE,\n    country TEXT NOT NULL,\n    short_name TEXT\n);\n\nCREATE TABLE IF NOT EXISTS venues (\n    venue_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    venue_name TEXT NOT NULL,\n    city TEXT NOT NULL,\n    country TEXT NOT NULL,\n    capacity INTEGER DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS series (\n    series_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    series_name TEXT NOT NULL,\n    host_country TEXT NOT NULL,\n    match_type TEXT NOT NULL,\n    start_date DATE NOT NULL,\n    total_matches INTEGER DEFAULT 1\n);\n\nCREATE TABLE IF NOT EXISTS players (\n    player_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    full_name TEXT NOT NULL,\n    team_id INTEGER,\n    playing_role TEXT CHECK(playing_role IN ('Batsman', 'Bowler', 'All-rounder', 'Wicket-keeper')),\n    batting_style TEXT,\n    bowling_style TEXT,\n    FOREIGN KEY (team_id) REFERENCES teams(team_id) ON DELETE SET NULL\n);\n\nCREATE TABLE IF NOT EXISTS player_career_stats (\n    stat_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    player_id INTEGER NOT NULL,\n    format TEXT CHECK(format IN ('Test', 'ODI', 'T20I')),\n    matches_played INTEGER DEFAULT 0,\n    runs_scored INTEGER DEFAULT 0,\n    batting_average REAL DEFAULT 0.0,\n    strike_rate REAL DEFAULT 0.0,\n    centuries INTEGER DEFAULT 0,\n    wickets_taken INTEGER DEFAULT 0,\n    bowling_average REAL DEFAULT 0.0,\n    economy_rate REAL DEFAULT 0.0,\n    catches INTEGER DEFAULT 0,\n    stumpings INTEGER DEFAULT 0,\n    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE,\n    UNIQUE(player_id, format)\n);\n\nCREATE TABLE IF NOT EXISTS matches (\n    match_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    series_id INTEGER,\n    match_description TEXT NOT NULL,\n    team1_id INTEGER NOT NULL,\n    team2_id INTEGER NOT NULL,\n    venue_id INTEGER NOT NULL,\n    match_date DATE NOT NULL,\n    format TEXT CHECK(format IN ('Test', 'ODI', 'T20I')),\n    winner_id INTEGER,\n    victory_margin INTEGER,\n    victory_type TEXT CHECK(victory_type IN ('runs', 'wickets', 'tie', 'no result')),\n    toss_winner_id INTEGER,\n    toss_decision TEXT CHECK(toss_decision IN ('bat', 'bowl')),\n    is_completed BOOLEAN DEFAULT 1,\n    FOREIGN KEY (series_id) REFERENCES series(series_id),\n    FOREIGN KEY (team1_id) REFERENCES teams(team_id),\n    FOREIGN KEY (team2_id) REFERENCES teams(team_id),\n    FOREIGN KEY (venue_id) REFERENCES venues(venue_id),\n    FOREIGN KEY (winner_id) REFERENCES teams(team_id),\n    FOREIGN KEY (toss_winner_id) REFERENCES teams(team_id)\n);\n\nCREATE TABLE IF NOT EXISTS innings (\n    innings_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    match_id INTEGER NOT NULL,\n    innings_number INTEGER NOT NULL,\n    batting_team_id INTEGER NOT NULL,\n    total_runs INTEGER DEFAULT 0,\n    wickets INTEGER DEFAULT 0,\n    overs REAL DEFAULT 0.0,\n    FOREIGN KEY (match_id) REFERENCES matches(match_id) ON DELETE CASCADE,\n    FOREIGN KEY (batting_team_id) REFERENCES teams(team_id)\n);\n\nCREATE TABLE IF NOT EXISTS batting_performances (\n    perf_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    match_id INTEGER NOT NULL,\n    innings_id INTEGER NOT NULL,\n    player_id INTEGER NOT NULL,\n    batting_position INTEGER NOT NULL,\n    runs_scored INTEGER DEFAULT 0,\n    balls_faced INTEGER DEFAULT 0,\n    fours INTEGER DEFAULT 0,\n    sixes INTEGER DEFAULT 0,\n    strike_rate REAL DEFAULT 0.0,\n    FOREIGN KEY (match_id) REFERENCES matches(match_id) ON DELETE CASCADE,\n    FOREIGN KEY (innings_id) REFERENCES innings(innings_id) ON DELETE CASCADE,\n    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS bowling_performances (\n    bowl_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    match_id INTEGER NOT NULL,\n    innings_id INTEGER NOT NULL,\n    player_id INTEGER NOT NULL,\n    overs_bowled REAL DEFAULT 0.0,\n    runs_conceded INTEGER DEFAULT 0,\n    wickets_taken INTEGER DEFAULT 0,\n    economy_rate REAL DEFAULT 0.0,\n    FOREIGN KEY (match_id) REFERENCES matches(match_id) ON DELETE CASCADE,\n    FOREIGN KEY (innings_id) REFERENCES innings(innings_id) ON DELETE CASCADE,\n    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE\n);\n", 'sql/indexes.sql': 'CREATE INDEX IF NOT EXISTS idx_matches_date ON matches(match_date);\nCREATE INDEX IF NOT EXISTS idx_matches_winner ON matches(winner_id);\nCREATE INDEX IF NOT EXISTS idx_matches_venue ON matches(venue_id);\nCREATE INDEX IF NOT EXISTS idx_players_team ON players(team_id);\nCREATE INDEX IF NOT EXISTS idx_batting_player ON batting_performances(player_id);\nCREATE INDEX IF NOT EXISTS idx_bowling_player ON bowling_performances(player_id);\n', 'sql/views.sql': 'CREATE VIEW IF NOT EXISTS v_match_results AS\nSELECT \n    m.match_id,\n    m.match_description,\n    t1.team_name AS team1,\n    t2.team_name AS team2,\n    tw.team_name AS winner,\n    m.victory_margin,\n    m.victory_type,\n    v.venue_name,\n    v.city,\n    m.match_date,\n    m.format\nFROM matches m\nJOIN teams t1 ON m.team1_id = t1.team_id\nJOIN teams t2 ON m.team2_id = t2.team_id\nLEFT JOIN teams tw ON m.winner_id = tw.team_id\nJOIN venues v ON m.venue_id = v.venue_id;\n\nCREATE VIEW IF NOT EXISTS v_team_wins AS\nSELECT \n    t.team_name,\n    COUNT(m.match_id) AS total_wins\nFROM teams t\nLEFT JOIN matches m ON t.team_id = m.winner_id\nGROUP BY t.team_id, t.team_name\nORDER BY total_wins DESC;\n', 'sql/seed.sql': "INSERT OR IGNORE INTO teams (team_id, team_name, country, short_name) VALUES\n(1, 'India', 'India', 'IND'),\n(2, 'Australia', 'Australia', 'AUS'),\n(3, 'England', 'England', 'ENG'),\n(4, 'South Africa', 'South Africa', 'SA');\n\nINSERT OR IGNORE INTO venues (venue_id, venue_name, city, country, capacity) VALUES\n(1, 'Narendra Modi Stadium', 'Ahmedabad', 'India', 132000),\n(2, 'Melbourne Cricket Ground', 'Melbourne', 'Australia', 100024),\n(3, 'Eden Gardens', 'Kolkata', 'India', 68000),\n(4, 'Lord\\'s Cricket Ground', 'London', 'England', 31100),\n(5, 'Wankhede Stadium', 'Mumbai', 'India', 33108);\n\nINSERT OR IGNORE INTO series (series_id, series_name, host_country, match_type, start_date, total_matches) VALUES\n(1, 'India tour of Australia 2024', 'Australia', 'Test', '2024-11-22', 5),\n(2, 'ICC Men\\'s T20 World Cup 2024', 'USA & West Indies', 'T20I', '2024-06-01', 55),\n(3, 'England tour of India 2024', 'India', 'Test', '2024-01-25', 5);\n\nINSERT OR IGNORE INTO players (player_id, full_name, team_id, playing_role, batting_style, bowling_style) VALUES\n(1, 'Virat Kohli', 1, 'Batsman', 'Right-hand bat', 'Right-arm medium'),\n(2, 'Rohit Sharma', 1, 'Batsman', 'Right-hand bat', 'Right-arm offbreak'),\n(3, 'Jasprit Bumrah', 1, 'Bowler', 'Right-hand bat', 'Right-arm fast'),\n(4, 'Ravindra Jadeja', 1, 'All-rounder', 'Left-hand bat', 'Slow left-arm orthodox'),\n(5, 'Pat Cummins', 2, 'Bowler', 'Right-hand bat', 'Right-arm fast'),\n(6, 'Glenn Maxwell', 2, 'All-rounder', 'Right-hand bat', 'Right-arm offbreak'),\n(7, 'Joe Root', 3, 'Batsman', 'Right-hand bat', 'Right-arm offbreak'),\n(8, 'Ben Stokes', 3, 'All-rounder', 'Left-hand bat', 'Right-arm fast-medium');\n\nINSERT OR IGNORE INTO player_career_stats (player_id, format, matches_played, runs_scored, batting_average, strike_rate, centuries, wickets_taken, bowling_average, economy_rate, catches, stumpings) VALUES\n(1, 'ODI', 295, 13906, 58.18, 93.5, 50, 5, 166.2, 6.2, 152, 0),\n(1, 'Test', 113, 8848, 49.15, 55.5, 29, 0, 0.0, 0.0, 111, 0),\n(1, 'T20I', 125, 4188, 48.69, 137.04, 1, 4, 51.0, 8.05, 54, 0),\n(2, 'ODI', 265, 10866, 49.16, 92.4, 31, 9, 64.3, 5.2, 93, 0),\n(3, 'ODI', 89, 79, 7.9, 48.2, 0, 149, 24.3, 4.6, 25, 0),\n(3, 'Test', 36, 212, 6.2, 35.1, 0, 159, 20.69, 2.76, 12, 0),\n(4, 'ODI', 197, 2756, 32.42, 85.2, 0, 220, 36.1, 4.88, 73, 0),\n(4, 'Test', 72, 3034, 36.11, 58.2, 4, 294, 24.1, 2.45, 43, 0),\n(5, 'ODI', 88, 452, 13.7, 72.1, 0, 141, 28.1, 5.23, 30, 0),\n(6, 'ODI', 142, 3934, 35.44, 126.8, 4, 74, 49.2, 5.58, 88, 0),\n(7, 'Test', 143, 12000, 50.2, 56.4, 32, 60, 44.5, 3.1, 190, 0),\n(8, 'Test', 105, 6350, 35.8, 59.2, 13, 201, 32.1, 3.3, 105, 0);\n\nINSERT OR IGNORE INTO matches (match_id, series_id, match_description, team1_id, team2_id, venue_id, match_date, format, winner_id, victory_margin, victory_type, toss_winner_id, toss_decision, is_completed) VALUES\n(1, 2, 'India vs Australia T20I Final', 1, 2, 1, '2024-06-29', 'T20I', 1, 24, 'runs', 2, 'bowl', 1),\n(2, 3, 'India vs England 1st Test', 1, 3, 3, '2024-01-25', 'Test', 3, 28, 'runs', 3, 'bat', 1),\n(3, 1, 'Australia vs India 1st Test', 2, 1, 2, '2024-11-22', 'Test', 1, 295, 'runs', 1, 'bat', 1),\n(4, 2, 'India vs South Africa Final', 1, 4, 5, '2024-06-29', 'T20I', 1, 7, 'runs', 1, 'bat', 1);\n\nINSERT OR IGNORE INTO innings (innings_id, match_id, innings_number, batting_team_id, total_runs, wickets, overs) VALUES\n(1, 1, 1, 1, 205, 5, 20.0),\n(2, 1, 2, 2, 181, 7, 20.0),\n(3, 4, 1, 1, 176, 7, 20.0),\n(4, 4, 2, 4, 169, 8, 20.0);\n\nINSERT OR IGNORE INTO batting_performances (match_id, innings_id, player_id, batting_position, runs_scored, balls_faced, fours, sixes, strike_rate) VALUES\n(1, 1, 2, 1, 92, 41, 7, 8, 224.39),\n(1, 1, 1, 2, 0, 5, 0, 0, 0.0),\n(4, 3, 1, 1, 76, 59, 6, 2, 128.81),\n(4, 3, 4, 6, 9, 2, 0, 1, 450.0);\n\nINSERT OR IGNORE INTO bowling_performances (match_id, innings_id, player_id, overs_bowled, runs_conceded, wickets_taken, economy_rate) VALUES\n(1, 2, 3, 4.0, 24, 2, 6.0),\n(1, 2, 4, 4.0, 32, 1, 8.0),\n(4, 4, 3, 4.0, 18, 2, 4.5);\n", 'sql/queries/q01.sql': "-- Q1: Find all players who represent India\nSELECT p.full_name, p.playing_role, p.batting_style, p.bowling_style FROM players p JOIN teams t ON p.team_id = t.team_id WHERE t.team_name = 'India';", 'sql/queries/q02.sql': "-- Q2: Matches played in the last 30 days\nSELECT m.match_description, t1.team_name AS team1, t2.team_name AS team2, v.venue_name || ', ' || v.city AS venue, m.match_date FROM matches m JOIN teams t1 ON m.team1_id = t1.team_id JOIN teams t2 ON m.team2_id = t2.team_id JOIN venues v ON m.venue_id = v.venue_id ORDER BY m.match_date DESC;", 'sql/queries/q03.sql': "-- Q3: Top 10 highest run scorers in ODI cricket\nSELECT p.full_name, pcs.runs_scored, pcs.batting_average, pcs.centuries FROM player_career_stats pcs JOIN players p ON pcs.player_id = p.player_id WHERE pcs.format = 'ODI' ORDER BY pcs.runs_scored DESC LIMIT 10;", 'sql/queries/q04.sql': '-- Q4: Venues with seating capacity > 50,000\nSELECT venue_name, city, country, capacity FROM venues WHERE capacity > 50000 ORDER BY capacity DESC;', 'sql/queries/q05.sql': '-- Q5: Total match wins per team\nSELECT t.team_name, COUNT(m.match_id) AS total_wins FROM teams t JOIN matches m ON t.team_id = m.winner_id GROUP BY t.team_id, t.team_name ORDER BY total_wins DESC;', 'sql/queries/q06.sql': '-- Q6: Count of players belonging to each playing role\nSELECT playing_role, COUNT(player_id) AS player_count FROM players WHERE playing_role IS NOT NULL GROUP BY playing_role ORDER BY player_count DESC;', 'sql/queries/q07.sql': '-- Q7: Highest individual batting score achieved in each cricket format\nSELECT format, MAX(runs_scored) AS highest_score FROM (SELECT m.format, bp.runs_scored FROM batting_performances bp JOIN matches m ON bp.match_id = m.match_id) GROUP BY format;', 'sql/queries/q08.sql': "-- Q8: Cricket series that started in the year 2024\nSELECT series_name, host_country, match_type, start_date, total_matches FROM series WHERE strftime('%Y', start_date) = '2024';", 'sql/queries/q09.sql': '-- Q9: All-rounders with > 1000 runs AND > 50 wickets\nSELECT p.full_name, pcs.format, pcs.runs_scored, pcs.wickets_taken FROM player_career_stats pcs JOIN players p ON pcs.player_id = p.player_id WHERE pcs.runs_scored > 1000 AND pcs.wickets_taken > 50;', 'sql/queries/q10.sql': '-- Q10: Details of the last 20 completed matches\nSELECT m.match_description, t1.team_name AS team1, t2.team_name AS team2, tw.team_name AS winner, m.victory_margin, m.victory_type, v.venue_name FROM matches m JOIN teams t1 ON m.team1_id = t1.team_id JOIN teams t2 ON m.team2_id = t2.team_id LEFT JOIN teams tw ON m.winner_id = tw.team_id JOIN venues v ON m.venue_id = v.venue_id WHERE m.is_completed = 1 ORDER BY m.match_date DESC LIMIT 20;', 'sql/queries/q11.sql': "-- Q11: Compare player performance across different formats\nSELECT p.full_name, SUM(CASE WHEN pcs.format = 'Test' THEN pcs.runs_scored ELSE 0 END) AS test_runs, SUM(CASE WHEN pcs.format = 'ODI' THEN pcs.runs_scored ELSE 0 END) AS odi_runs, SUM(CASE WHEN pcs.format = 'T20I' THEN pcs.runs_scored ELSE 0 END) AS t20i_runs, ROUND(AVG(pcs.batting_average), 2) AS overall_avg FROM player_career_stats pcs JOIN players p ON pcs.player_id = p.player_id GROUP BY p.player_id, p.full_name HAVING COUNT(DISTINCT pcs.format) >= 2;", 'sql/queries/q12.sql': '-- Q12: Home vs Away performance analysis\nSELECT t.team_name, SUM(CASE WHEN v.country = t.country THEN 1 ELSE 0 END) AS home_wins, SUM(CASE WHEN v.country != t.country THEN 1 ELSE 0 END) AS away_wins FROM matches m JOIN teams t ON m.winner_id = t.team_id JOIN venues v ON m.venue_id = v.venue_id GROUP BY t.team_id, t.team_name;', 'sql/queries/q13.sql': '-- Q13: Batting partnerships (consecutive batsmen >= 100 combined runs)\nSELECT bp1.innings_id, p1.full_name AS batsman1, p2.full_name AS batsman2, (bp1.runs_scored + bp2.runs_scored) AS combined_runs FROM batting_performances bp1 JOIN batting_performances bp2 ON bp1.innings_id = bp2.innings_id AND bp2.batting_position = bp1.batting_position + 1 JOIN players p1 ON bp1.player_id = p1.player_id JOIN players p2 ON bp2.player_id = p2.player_id WHERE (bp1.runs_scored + bp2.runs_scored) >= 50;', 'sql/queries/q14.sql': '-- Q14: Bowling performance at venues\nSELECT v.venue_name, p.full_name, COUNT(DISTINCT m.match_id) AS matches_played, ROUND(AVG(bp.economy_rate), 2) AS avg_economy, SUM(bp.wickets_taken) AS total_wickets FROM bowling_performances bp JOIN matches m ON bp.match_id = m.match_id JOIN venues v ON m.venue_id = v.venue_id JOIN players p ON bp.player_id = p.player_id GROUP BY v.venue_id, p.player_id;', 'sql/queries/q15.sql': "-- Q15: Players performing in close matches (<50 runs or <5 wickets)\nSELECT p.full_name, COUNT(DISTINCT m.match_id) AS close_matches_played, ROUND(AVG(bp.runs_scored), 2) AS avg_runs, SUM(CASE WHEN m.winner_id = p.team_id THEN 1 ELSE 0 END) AS team_wins FROM batting_performances bp JOIN matches m ON bp.match_id = m.match_id JOIN players p ON bp.player_id = p.player_id WHERE (m.victory_type = 'runs' AND m.victory_margin < 50) OR (m.victory_type = 'wickets' AND m.victory_margin < 5) GROUP BY p.player_id, p.full_name;", 'sql/queries/q16.sql': "-- Q16: Yearly batting performance trend since 2020\nSELECT strftime('%Y', m.match_date) AS match_year, p.full_name, ROUND(AVG(bp.runs_scored), 2) AS avg_runs, ROUND(AVG(bp.strike_rate), 2) AS avg_strike_rate FROM batting_performances bp JOIN matches m ON bp.match_id = m.match_id JOIN players p ON bp.player_id = p.player_id WHERE m.match_date >= '2020-01-01' GROUP BY match_year, p.player_id, p.full_name;", 'sql/queries/q17.sql': '-- Q17: Toss advantage investigation\nSELECT toss_decision, COUNT(match_id) AS total_matches, SUM(CASE WHEN toss_winner_id = winner_id THEN 1 ELSE 0 END) AS matches_won, ROUND(SUM(CASE WHEN toss_winner_id = winner_id THEN 1.0 ELSE 0.0 END) / COUNT(match_id) * 100, 2) AS win_percentage FROM matches WHERE toss_decision IS NOT NULL GROUP BY toss_decision;', 'sql/queries/q18.sql': "-- Q18: Economical limited-overs bowlers (ODI and T20I)\nSELECT p.full_name, ROUND(AVG(pcs.economy_rate), 2) AS overall_economy, SUM(pcs.wickets_taken) AS total_wickets FROM player_career_stats pcs JOIN players p ON pcs.player_id = p.player_id WHERE pcs.format IN ('ODI', 'T20I') GROUP BY p.player_id, p.full_name ORDER BY overall_economy ASC;", 'sql/queries/q19.sql': '-- Q19: Batsmen scoring consistency\nSELECT p.full_name, ROUND(AVG(bp.runs_scored), 2) AS avg_runs FROM batting_performances bp JOIN players p ON bp.player_id = p.player_id GROUP BY p.player_id, p.full_name ORDER BY avg_runs DESC;', 'sql/queries/q20.sql': "-- Q20: Multi-format player analysis\nSELECT p.full_name, SUM(CASE WHEN pcs.format = 'Test' THEN pcs.matches_played ELSE 0 END) AS test_matches, SUM(CASE WHEN pcs.format = 'ODI' THEN pcs.matches_played ELSE 0 END) AS odi_matches, SUM(CASE WHEN pcs.format = 'T20I' THEN pcs.matches_played ELSE 0 END) AS t20i_matches, ROUND(AVG(pcs.batting_average), 2) AS avg_batting_avg FROM player_career_stats pcs JOIN players p ON pcs.player_id = p.player_id GROUP BY p.player_id, p.full_name;", 'sql/queries/q21.sql': '-- Q21: Comprehensive weighted performance ranking system\nSELECT p.full_name, pcs.format, ROUND(((pcs.runs_scored * 0.01) + (pcs.batting_average * 0.5) + (pcs.strike_rate * 0.3)), 2) AS batting_pts, ROUND(((pcs.wickets_taken * 2) + ((50 - pcs.bowling_average) * 0.5) + ((6 - pcs.economy_rate) * 2)), 2) AS bowling_pts, ROUND(((pcs.catches * 3) + (pcs.stumpings * 5)), 2) AS fielding_pts, ROUND(((pcs.runs_scored * 0.01) + (pcs.batting_average * 0.5) + (pcs.strike_rate * 0.3)) + ((pcs.wickets_taken * 2) + ((50 - pcs.bowling_average) * 0.5) + ((6 - pcs.economy_rate) * 2)) + ((pcs.catches * 3) + (pcs.stumpings * 5)), 2) AS total_ranking_score FROM player_career_stats pcs JOIN players p ON pcs.player_id = p.player_id ORDER BY total_ranking_score DESC;', 'sql/queries/q22.sql': '-- Q22: Head-to-head match prediction analysis between teams\nSELECT CASE WHEN team1_id < team2_id THEN team1_id ELSE team2_id END AS t1_id, CASE WHEN team1_id < team2_id THEN team2_id ELSE team1_id END AS t2_id, COUNT(match_id) AS total_h2h_matches, SUM(CASE WHEN winner_id = team1_id THEN 1 ELSE 0 END) AS team1_wins, SUM(CASE WHEN winner_id = team2_id THEN 1 ELSE 0 END) AS team2_wins FROM matches GROUP BY t1_id, t2_id;', 'sql/queries/q23.sql': "-- Q23: Recent player form and momentum\nSELECT p.full_name, COUNT(bp.perf_id) AS recent_innings, ROUND(AVG(bp.runs_scored), 2) AS recent_avg, SUM(CASE WHEN bp.runs_scored >= 50 THEN 1 ELSE 0 END) AS fifties_count, CASE WHEN AVG(bp.runs_scored) >= 50 THEN 'Excellent Form' WHEN AVG(bp.runs_scored) >= 35 THEN 'Good Form' WHEN AVG(bp.runs_scored) >= 20 THEN 'Average Form' ELSE 'Poor Form' END AS form_category FROM batting_performances bp JOIN players p ON bp.player_id = p.player_id GROUP BY p.player_id, p.full_name;", 'sql/queries/q24.sql': '-- Q24: Batting partnerships synergy ranking\nSELECT p1.full_name AS batter1, p2.full_name AS batter2, COUNT(*) AS partnership_count, ROUND(AVG(bp1.runs_scored + bp2.runs_scored), 2) AS avg_partnership_runs, MAX(bp1.runs_scored + bp2.runs_scored) AS highest_partnership FROM batting_performances bp1 JOIN batting_performances bp2 ON bp1.innings_id = bp2.innings_id AND bp2.batting_position = bp1.batting_position + 1 JOIN players p1 ON bp1.player_id = p1.player_id JOIN players p2 ON bp2.player_id = p2.player_id GROUP BY batter1, batter2 ORDER BY avg_partnership_runs DESC;', 'sql/queries/q25.sql': "-- Q25: Time-series player quarterly performance evolution\nSELECT p.full_name, strftime('%Y', m.match_date) || '-Q' || ((strftime('%m', m.match_date) - 1) / 3 + 1) AS quarter, ROUND(AVG(bp.runs_scored), 2) AS quarterly_avg_runs, ROUND(AVG(bp.strike_rate), 2) AS quarterly_avg_sr, CASE WHEN AVG(bp.runs_scored) > 40 THEN 'Career Ascending' WHEN AVG(bp.runs_scored) > 25 THEN 'Career Stable' ELSE 'Career Declining' END AS career_phase FROM batting_performances bp JOIN matches m ON bp.match_id = m.match_id JOIN players p ON bp.player_id = p.player_id GROUP BY p.player_id, p.full_name, quarter;", 'database/connection.py': 'import os\nimport sqlite3\nimport math\nfrom sqlalchemy import create_engine\nfrom config import DATABASE_URL\n\nos.makedirs("data", exist_ok=True)\nos.makedirs("logs", exist_ok=True)\n\ndef sqlite_connect_hook():\n    db_path = DATABASE_URL.replace("sqlite:///", "")\n    conn = sqlite3.connect(db_path)\n    conn.execute("PRAGMA foreign_keys = ON;")\n    conn.create_function("SQRT", 1, math.sqrt)\n    return conn\n\nengine = create_engine("sqlite:///data/cricket.db", creator=sqlite_connect_hook, echo=False)\n', 'database/repositories.py': 'import pandas as pd\nfrom database.connection import engine\nfrom sqlalchemy import text\n\ndef get_all_players():\n    query = """\n        SELECT p.player_id, p.full_name, t.team_name, p.playing_role, p.batting_style, p.bowling_style\n        FROM players p LEFT JOIN teams t ON p.team_id = t.team_id\n        ORDER BY p.full_name ASC;\n    """\n    return pd.read_sql(query, engine)\n\ndef add_player(full_name, team_id, role, bat_style, bowl_style):\n    with engine.begin() as conn:\n        conn.execute(\n            text("""\n                INSERT INTO players (full_name, team_id, playing_role, batting_style, bowling_style)\n                VALUES (:name, :team, :role, :bat, :bowl);\n            """),\n            {"name": full_name, "team": team_id, "role": role, "bat": bat_style, "bowl": bowl_style}\n        )\n\ndef update_player(player_id, full_name, role, bat_style, bowl_style):\n    with engine.begin() as conn:\n        conn.execute(\n            text("""\n                UPDATE players \n                SET full_name = :name, playing_role = :role, batting_style = :bat, bowling_style = :bowl\n                WHERE player_id = :id;\n            """),\n            {"id": player_id, "name": full_name, "role": role, "bat": bat_style, "bowl": bowl_style}\n        )\n\ndef delete_player(player_id):\n    with engine.begin() as conn:\n        conn.execute(text("DELETE FROM players WHERE player_id = :id;"), {"id": player_id})\n\ndef get_all_teams():\n    return pd.read_sql("SELECT team_id, team_name FROM teams ORDER BY team_name;", engine)\n\ndef get_all_matches():\n    query = """\n        SELECT m.match_id, m.match_description, t1.team_name AS team1, t2.team_name AS team2, \n               v.venue_name, m.match_date, m.format, tw.team_name AS winner\n        FROM matches m\n        JOIN teams t1 ON m.team1_id = t1.team_id\n        JOIN teams t2 ON m.team2_id = t2.team_id\n        JOIN venues v ON m.venue_id = v.venue_id\n        LEFT JOIN teams tw ON m.winner_id = tw.team_id\n        ORDER BY m.match_date DESC;\n    """\n    return pd.read_sql(query, engine)\n', 'api/cricbuzz_client.py': 'import requests\nfrom config import RAPIDAPI_KEY, RAPIDAPI_HOST, BASE_API_URL\n\nclass CricbuzzClient:\n    def __init__(self):\n        self.headers = {\n            "x-rapidapi-key": RAPIDAPI_KEY,\n            "x-rapidapi-host": RAPIDAPI_HOST\n        }\n\n    def test_connection(self):\n        if not RAPIDAPI_KEY or RAPIDAPI_KEY == "your_rapidapi_key_here":\n            return False, "API Key is missing or default placeholder."\n        try:\n            resp = requests.get(f"{BASE_API_URL}/matches/v1/live", headers=self.headers, timeout=10)\n            return resp.status_code == 200, f"Status: {resp.status_code}"\n        except Exception as e:\n            return False, str(e)\n\n    def get_live_matches(self):\n        if not RAPIDAPI_KEY:\n            return self._mock_live_data()\n        try:\n            resp = requests.get(f"{BASE_API_URL}/matches/v1/live", headers=self.headers, timeout=10)\n            if resp.status_code == 200:\n                return resp.json()\n        except Exception:\n            pass\n        return self._mock_live_data()\n\n    def _mock_live_data(self):\n        return {\n            "typeMatches": [\n                {\n                    "matchType": "International",\n                    "seriesMatches": [\n                        {\n                            "seriesAdWrapper": {\n                                "seriesName": "T20 International Championship",\n                                "matches": [\n                                    {\n                                        "matchInfo": {\n                                            "matchDesc": "Final",\n                                            "team1": {"teamName": "India", "teamSName": "IND"},\n                                            "team2": {"teamName": "Australia", "teamSName": "AUS"},\n                                            "venueInfo": {"ground": "Narendra Modi Stadium", "city": "Ahmedabad"},\n                                            "status": "India won by 24 runs"\n                                        },\n                                        "matchScore": {\n                                            "team1Score": {"inngs1": {"runs": 205, "wickets": 5, "overs": 20.0}},\n                                            "team2Score": {"inngs1": {"runs": 181, "wickets": 7, "overs": 20.0}}\n                                        }\n                                    }\n                                ]\n                            }\n                        }\n                    ]\n                }\n            ]\n        }\n', 'utils/charts.py': 'import plotly.express as px\n\ndef create_bar_chart(df, x_col, y_col, title):\n    fig = px.bar(df, x=x_col, y=y_col, title=title, template="plotly_white", color=y_col)\n    fig.update_layout(margin=dict(l=20, r=20, t=40, b=20))\n    return fig\n\ndef create_pie_chart(df, names_col, values_col, title):\n    fig = px.pie(df, names=names_col, values=values_col, title=title, hole=0.4)\n    fig.update_layout(margin=dict(l=20, r=20, t=40, b=20))\n    return fig\n', 'init_database.py': 'import os\nimport sqlite3\nimport math\n\nDB_PATH = "data/cricket.db"\nos.makedirs("data", exist_ok=True)\nos.makedirs("logs", exist_ok=True)\n\ndef init_db():\n    conn = sqlite3.connect(DB_PATH)\n    conn.execute("PRAGMA foreign_keys = ON;")\n    conn.create_function("SQRT", 1, math.sqrt)\n    \n    scripts = ["sql/schema.sql", "sql/indexes.sql", "sql/views.sql", "sql/seed.sql"]\n    for s in scripts:\n        if os.path.exists(s):\n            with open(s, "r", encoding="utf-8") as f:\n                conn.executescript(f.read())\n            print(f"Executed: {s}")\n    conn.commit()\n    conn.close()\n    print("Database initialized successfully at data/cricket.db")\n\nif __name__ == "__main__":\n    init_db()\n', 'app.py': 'import streamlit as st\nimport pandas as pd\nfrom database.connection import engine\n\nst.set_page_config(page_title="Cricbuzz LiveStats", page_icon="🏏", layout="wide")\n\nst.title("🏏 Cricbuzz LiveStats Dashboard")\nst.markdown("**Real-Time Cricket Insights & SQL-Based Analytics**")\nst.markdown("---")\n\ncol1, col2, col3, col4 = st.columns(4)\n\ntry:\n    p_count = pd.read_sql("SELECT COUNT(*) AS c FROM players;", engine)["c"][0]\n    m_count = pd.read_sql("SELECT COUNT(*) AS c FROM matches;", engine)["c"][0]\n    t_count = pd.read_sql("SELECT COUNT(*) AS c FROM teams;", engine)["c"][0]\n    v_count = pd.read_sql("SELECT COUNT(*) AS c FROM venues;", engine)["c"][0]\nexcept Exception:\n    p_count, m_count, t_count, v_count = 0, 0, 0, 0\n\ncol1.metric("Total Players", p_count)\ncol2.metric("Total Matches", m_count)\ncol3.metric("Teams Registered", t_count)\ncol4.metric("Venues Tracked", v_count)\n\nst.markdown("---")\nst.subheader("📌 Project Navigation & System Modules")\nst.markdown("""\nUse the **sidebar menu** to access all modules:\n- **1_Live_Matches:** Real-time matches, live scorecards, and commentary feeds.\n- **2_Top_Stats:** Batting and bowling leaderboards visualised via charts.\n- **3_SQL_Analytics:** All 25 analytical SQL questions with results and query executor.\n- **4_CRUD_Operations:** Manage cricket database records (Create, Read, Update, Delete).\n- **5_Settings:** API connection diagnostics, venue data import, and database resets.\n""")\n', 'pages/1_Live_Matches.py': 'import streamlit as st\nfrom api.cricbuzz_client import CricbuzzClient\n\nst.set_page_config(page_title="Live Matches", page_icon="🔴", layout="wide")\nst.title("🔴 Live Cricket Matches")\n\nclient = CricbuzzClient()\ndata = client.get_live_matches()\n\nmatches_found = []\nfor type_match in data.get("typeMatches", []):\n    m_type = type_match.get("matchType", "Match")\n    for series in type_match.get("seriesMatches", []):\n        s_wrapper = series.get("seriesAdWrapper", {})\n        s_name = s_wrapper.get("seriesName", "Tournament")\n        for match in s_wrapper.get("matches", []):\n            info = match.get("matchInfo", {})\n            score = match.get("matchScore", {})\n            matches_found.append({"type": m_type, "series": s_name, "info": info, "score": score})\n\nif matches_found:\n    for m in matches_found:\n        info = m["info"]\n        score = m["score"]\n        t1 = info.get("team1", {}).get("teamName", "Team 1")\n        t2 = info.get("team2", {}).get("teamName", "Team 2")\n        status = info.get("status", "Live")\n        venue = info.get("venueInfo", {}).get("ground", "Ground")\n        \n        with st.container():\n            st.subheader(f"{t1} vs {t2}")\n            st.caption(f"Series: {m[\'series\']} | Venue: {venue}")\n            st.info(f"Status: **{status}**")\n            \n            s1 = score.get("team1Score", {}).get("inngs1", {})\n            s2 = score.get("team2Score", {}).get("inngs1", {})\n            if s1 or s2:\n                c1, c2 = st.columns(2)\n                if s1:\n                    c1.metric(t1, f"{s1.get(\'runs\', 0)}/{s1.get(\'wickets\', 0)} ({s1.get(\'overs\', 0)} ov)")\n                if s2:\n                    c2.metric(t2, f"{s2.get(\'runs\', 0)}/{s2.get(\'wickets\', 0)} ({s2.get(\'overs\', 0)} ov)")\n            st.markdown("---")\nelse:\n    st.warning("No ongoing live fixtures found.")\n', 'pages/2_Top_Stats.py': 'import streamlit as st\nimport pandas as pd\nfrom database.connection import engine\nfrom utils.charts import create_bar_chart\n\nst.set_page_config(page_title="Top Stats", page_icon="📊", layout="wide")\nst.title("📊 Player Leaderboards & Top Stats")\n\nformat_choice = st.selectbox("Select Cricket Format", ["ODI", "Test", "T20I"])\n\ndf_batting = pd.read_sql(f"""\n    SELECT p.full_name, pcs.runs_scored, pcs.batting_average, pcs.strike_rate, pcs.centuries\n    FROM player_career_stats pcs\n    JOIN players p ON pcs.player_id = p.player_id\n    WHERE pcs.format = \'{format_choice}\'\n    ORDER BY pcs.runs_scored DESC LIMIT 10;\n""", engine)\n\nc1, c2 = st.columns(2)\nwith c1:\n    st.subheader(f"Top Run Scorers ({format_choice})")\n    st.dataframe(df_batting, use_container_width=True)\n\nwith c2:\n    if not df_batting.empty:\n        fig = create_bar_chart(df_batting, "full_name", "runs_scored", f"Highest Run Scorers ({format_choice})")\n        st.plotly_chart(fig, use_container_width=True)\n\nst.markdown("---")\ndf_bowling = pd.read_sql(f"""\n    SELECT p.full_name, pcs.wickets_taken, pcs.bowling_average, pcs.economy_rate\n    FROM player_career_stats pcs\n    JOIN players p ON pcs.player_id = p.player_id\n    WHERE pcs.format = \'{format_choice}\' AND pcs.wickets_taken > 0\n    ORDER BY pcs.wickets_taken DESC LIMIT 10;\n""", engine)\n\nc3, c4 = st.columns(2)\nwith c3:\n    st.subheader(f"Top Wicket Takers ({format_choice})")\n    st.dataframe(df_bowling, use_container_width=True)\n\nwith c4:\n    if not df_bowling.empty:\n        fig_bowl = create_bar_chart(df_bowling, "full_name", "wickets_taken", f"Most Wickets ({format_choice})")\n        st.plotly_chart(fig_bowl, use_container_width=True)\n', 'pages/3_SQL_Analytics.py': 'import streamlit as st\nimport pandas as pd\nimport os\nfrom database.connection import engine\nfrom utils.charts import create_bar_chart\n\nst.set_page_config(page_title="SQL Analytics", page_icon="⚡", layout="wide")\nst.title("⚡ 25 SQL Analytical Queries")\n\nquestion_list = [f"Question {i+1}" for i in range(25)]\nselected_q = st.selectbox("Choose Question to Inspect", question_list)\nq_num = selected_q.split()[1].zfill(2)\nq_file = f"sql/queries/q{q_num}.sql"\n\nif os.path.exists(q_file):\n    with open(q_file, "r") as f:\n        sql_content = f.read()\n    \n    st.markdown(f"### Query: {selected_q}")\n    st.code(sql_content, language="sql")\n    \n    try:\n        df_res = pd.read_sql(sql_content, engine)\n        st.dataframe(df_res, use_container_width=True)\n        \n        # Download button\n        csv = df_res.to_csv(index=False).encode(\'utf-8\')\n        st.download_button("📥 Download Results CSV", data=csv, file_name=f"query_{q_num}_results.csv", mime="text/csv")\n    except Exception as e:\n        st.error(f"Error executing query: {e}")\n\nst.markdown("---")\nst.subheader("🔍 Custom Read-Only SQL Console")\nuser_query = st.text_area("Type your SELECT query:", "SELECT * FROM teams LIMIT 5;")\nif st.button("Run Query"):\n    if not user_query.strip().upper().startswith(("SELECT", "WITH")):\n        st.warning("Only read-only SELECT or WITH queries are permitted here.")\n    else:\n        try:\n            custom_df = pd.read_sql(user_query, engine)\n            st.dataframe(custom_df, use_container_width=True)\n        except Exception as err:\n            st.error(f"Execution Error: {err}")\n', 'pages/4_CRUD_Operations.py': 'import streamlit as st\nimport pandas as pd\nfrom database.repositories import get_all_players, add_player, update_player, delete_player, get_all_teams\n\nst.set_page_config(page_title="CRUD Operations", page_icon="✏️", layout="wide")\nst.title("✏️ Player Database Management (CRUD)")\n\ntab1, tab2, tab3 = st.tabs(["View Players", "Add Player", "Edit / Delete Player"])\n\nteams_df = get_all_teams()\nteam_dict = dict(zip(teams_df["team_name"], teams_df["team_id"]))\n\nwith tab1:\n    st.subheader("Current Players List")\n    players_df = get_all_players()\n    st.dataframe(players_df, use_container_width=True)\n\nwith tab2:\n    st.subheader("Register New Player")\n    with st.form("add_player_form"):\n        name = st.text_input("Full Name")\n        team = st.selectbox("Team", list(team_dict.keys()))\n        role = st.selectbox("Role", ["Batsman", "Bowler", "All-rounder", "Wicket-keeper"])\n        bat = st.selectbox("Batting Style", ["Right-hand bat", "Left-hand bat"])\n        bowl = st.selectbox("Bowling Style", ["Right-arm fast", "Right-arm offbreak", "Slow left-arm orthodox", "None"])\n        \n        submitted = st.form_submit_button("Add Player")\n        if submitted:\n            if name.strip():\n                add_player(name, team_dict[team], role, bat, bowl)\n                st.success(f"Player \'{name}\' added successfully!")\n                st.rerun()\n            else:\n                st.error("Player name cannot be empty.")\n\nwith tab3:\n    st.subheader("Modify Player Details")\n    if not players_df.empty:\n        p_names = dict(zip(players_df["full_name"], players_df["player_id"]))\n        sel_name = st.selectbox("Select Player", list(p_names.keys()))\n        sel_id = p_names[sel_name]\n        \n        row = players_df[players_df["player_id"] == sel_id].iloc[0]\n        with st.form("edit_player_form"):\n            new_name = st.text_input("Name", value=row["full_name"])\n            new_role = st.selectbox("Role", ["Batsman", "Bowler", "All-rounder", "Wicket-keeper"], index=["Batsman", "Bowler", "All-rounder", "Wicket-keeper"].index(row["playing_role"]) if row["playing_role"] in ["Batsman", "Bowler", "All-rounder", "Wicket-keeper"] else 0)\n            new_bat = st.text_input("Batting Style", value=row["batting_style"] or "Right-hand bat")\n            new_bowl = st.text_input("Bowling Style", value=row["bowling_style"] or "Right-arm fast")\n            \n            c1, c2 = st.columns(2)\n            update_btn = c1.form_submit_button("Update Player")\n            delete_btn = c2.form_submit_button("Delete Player")\n            \n            if update_btn:\n                update_player(sel_id, new_name, new_role, new_bat, new_bowl)\n                st.success("Player updated successfully!")\n                st.rerun()\n            if delete_btn:\n                delete_player(sel_id)\n                st.warning(f"Player \'{new_name}\' deleted!")\n                st.rerun()\n', 'pages/5_Settings.py': 'import streamlit as st\nimport os\nfrom api.cricbuzz_client import CricbuzzClient\nfrom init_database import init_db\n\nst.set_page_config(page_title="Settings", page_icon="⚙️", layout="wide")\nst.title("⚙️ System Diagnostics & Settings")\n\nst.subheader("API Connectivity Test")\nclient = CricbuzzClient()\nif st.button("Test Cricbuzz RapidAPI Connection"):\n    success, msg = client.test_connection()\n    if success:\n        st.success(f"Connection OK! {msg}")\n    else:\n        st.warning(f"Notice: {msg} (Application running in offline mock/database mode)")\n\nst.markdown("---")\nst.subheader("Database Maintenance")\nif st.button("Reset Database to Seed State"):\n    init_db()\n    st.success("Database restored to seed state with schema and tables!")\n', 'tests/test_crud.py': 'import pytest\nimport sqlite3\nimport pandas as pd\nfrom database.connection import engine\nfrom database.repositories import get_all_players, add_player, delete_player\n\ndef test_database_connection():\n    assert engine is not None\n\ndef test_get_players():\n    df = get_all_players()\n    assert isinstance(df, pd.DataFrame)\n    assert len(df) >= 0\n\ndef test_add_and_delete_player():\n    add_player("Test Player", 1, "Batsman", "Right-hand bat", "None")\n    df = get_all_players()\n    assert "Test Player" in df["full_name"].values\n    \n    p_id = df[df["full_name"] == "Test Player"]["player_id"].values[0]\n    delete_player(p_id)\n    df_after = get_all_players()\n    assert "Test Player" not in df_after["full_name"].values\n', 'Dockerfile': 'FROM python:3.10-slim\n\nWORKDIR /app\n\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\n\nCOPY . .\n\nRUN python init_database.py\n\nEXPOSE 8501\n\nCMD ["streamlit", "run", "app.py", "--server.port=8501", "--server.address=0.0.0.0"]\n'}


